@Test
public void verifyHmacSha1MethodAlgorithm() throws Exception {
    // the consumer secret
    HmacSha1Key hmacKey = new HmacSha1Key("kd94hf93k423kf44");
    this.verifySignature(hmacKey, hmacKey, new HmacSha1MethodAlgorithm(), "tR3+Ty81lMeYAr/Fid0kMTYa/WM=");
}

@Test
public void verifyPlaintextMethodAlgorithm() throws Exception {
    // the consumer secret
    PlaintextKey hmacKey = new PlaintextKey("kd94hf93k423kf44");
    this.verifySignature(hmacKey, hmacKey, new PlaintextMethodAlgorithm(), "kd94hf93k423kf44&pfkkdhi9sl3r4s00");
}
